#!/usr/bin/env node
// amplify_outputs.json is generated by `npx ampx sandbox` (local) or `ampx pipeline-deploy`
// (Amplify CI) and is git-ignored. If it is missing, write a minimal stub so the app still
// builds; the inquiry form detects the missing data config and falls back to WhatsApp/email.
import { existsSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const file = fileURLToPath(new URL("../amplify_outputs.json", import.meta.url));
if (!existsSync(file)) {
  writeFileSync(file, `${JSON.stringify({ version: "1" }, null, 2)}\n`);
  console.log("amplify_outputs.json missing — wrote a stub (form will use the WhatsApp/email fallback).");
}
